## Submitted testbench
```systemverilog
`timescale 1ns / 1ps
module tb;

  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD   = 8;                // 125 MHz clock
  localparam logic [15:0] PRESCALE_VAL = 16'd5;   // preset prescale value

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic clk = 1'b0;
  logic rst = 1'b0;
  logic rxd = 1'b1;                               // UART_RX input
  logic [15:0] prescale_val = PRESCALE_VAL;       // configuration to DUT

  // ------------------------------------------------------------
  // DUT ports (uart_rx)
  // ------------------------------------------------------------
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;
  logic        busy;
  logic        overrun_error;
  logic        frame_error;

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Helper tasks
  // ------------------------------------------------------------
  // Wait for N falling‑edge clock cycles
  task automatic wait_n_clks (input int n);
    repeat (n) @(negedge clk);
  endtask

  // Transmit one UART frame (8N1)
  //   data_byte – byte to be sent (LSB first)
  //   stop_low  – 1 => stop bit forced low (causes frame_error)
  task automatic send_frame (input byte unsigned data_byte, input bit stop_low);
    // --- start bit (low) ---
    rxd = 1'b0;
    wait_n_clks(int'(PRESCALE_VAL) * 8);

    // --- data bits LSB first ---
    for (int i = 0; i < 8; i = i + 1) begin
      rxd = data_byte[i];
      wait_n_clks(int'(PRESCALE_VAL) * 8);
    end

    // --- stop bit ---
    rxd = stop_low ? 1'b0 : 1'b1;
    wait_n_clks(int'(PRESCALE_VAL) * 8);

    // Return line to idle state
    rxd = 1'b1;
  endtask

  // Wait until frame_error becomes asserted (polling timeout)
  task automatic wait_for_frame_error;
    int unsigned limit = 1000;
    while (frame_error == 1'b0 && limit != 0) begin
      wait_n_clks(1);
      limit = limit - 1;
    end
    if (frame_error !== 1'b1) begin
      $error("frame_error never asserted");
    end
  endtask

  // ------------------------------------------------------------
  // Reset sequence and stimulus
  // ------------------------------------------------------------
  initial begin
    // --- initial reset -------------------------------------------------
    rst = 1'b1;
    rxd = 1'b1;
    prescale_val = PRESCALE_VAL;
    wait_n_clks(20);
    rst = 1'b0;
    wait_n_clks(20);
    rst = 1'b1;
    wait_n_clks(20);
    rst = 1'b0;
    wait_n_clks(50);

    // ----------------------------------------------------------------
    // 1) Send a *good* frame with data 0x3C and a high stop bit.
    //    This puts the word 0x3C into the output and asserts m_axis_tvalid.
    // ----------------------------------------------------------------
    send_frame(8'h3C, 1'b0);          // stop bit = high (normal)

    // Allow the DUT to present the word and keep m_axis_tvalid high.
    wait_n_clks(200);

    // ----------------------------------------------------------------
    // 2) Send a second frame with a *low* stop bit.  The pending word
    //    (0x3C) must still be present, and a frame_error must be generated.
    // ----------------------------------------------------------------
    send_frame(8'hA5, 1'b1);            // stop bit = low → frame_error

    // Wait for the error to be flagged.
    wait_for_frame_error();

    // Short pause to let the coverage point be evaluated.
    wait_n_clks(10);

    // ----------------------------------------------------------------
    // End of simulation – $finish guarantees a clean exit.
    // ----------------------------------------------------------------
    $finish;
  end

endmodule
```

